Office.onReady(() => {

  const url = window.location.href;

  if (url.includes("action=send")) {

    document.body.innerHTML =
      "<h1>Send To ERP</h1>" +
      "<button id='btnSend'>SEND</button>" +
      "<div id='result'></div>";

    const btn = document.getElementById("btnSend");

    btn.addEventListener("click", async function () {

  try {

    const item = Office.context.mailbox.item;

    if (!item) {

      document.getElementById("result").innerHTML =
        "<p>No mail item</p>";

      return;
    }

    if (!item.attachments ||
        item.attachments.length === 0) {

      document.getElementById("result").innerHTML =
        "<p>No attachments</p>";

      return;
    }

    const attachment = item.attachments[0];

    document.getElementById("result").innerHTML =
      "<p>Loading attachment...</p>";

    item.getAttachmentContentAsync(
      attachment.id,
      async function (result) {

        try {

          if (result.status !== Office.AsyncResultStatus.Succeeded) {

            document.getElementById("result").innerHTML =
              "<p>Failed to load attachment</p>";

            return;
          }

          const content = result.value.content;

          document.getElementById("result").innerHTML =
            "<p>Sending to localhost...</p>";

          const response = await fetch(
            "http://localhost:5001/process",
            {
              method: "POST",
              headers: {
                "Content-Type": "application/json"
              },
              body: JSON.stringify({
                fileName: attachment.name,
                contentBase64: content
              })
            });

          const data = await response.json();

          document.getElementById("result").innerHTML =
            "<p>SAVED: " + data.savedTo + "</p>";
        }
        catch (e) {

          document.getElementById("result").innerHTML =
            "<p>ERROR: " + e + "</p>";
        }
      });
  }
  catch (e) {

    document.getElementById("result").innerHTML =
      "<p>ERROR: " + e + "</p>";
  }
});
  }

  else if (url.includes("action=archive")) {

    document.body.innerHTML =
      "<h1>Archive</h1>" +
      "<button id='btnArchive'>ARCHIVE</button>" +
      "<div id='result'></div>";

    const btn = document.getElementById("btnArchive");

    btn.addEventListener("click", function () {
      document.getElementById("result").innerHTML =
        "<p>ARCHIVE CLICKED</p>";
    });
  }

  else if (url.includes("action=settings")) {

    document.body.innerHTML =
      "<h1>Settings</h1>" +
      "<button id='btnSettings'>SAVE</button>" +
      "<div id='result'></div>";

    const btn = document.getElementById("btnSettings");

    btn.addEventListener("click", async function () {

  try {

    const item = Office.context.mailbox.item;

    if (!item) {

      document.getElementById("result").innerHTML =
        "<p>No mail item</p>";

      return;
    }

    if (!item.attachments ||
        item.attachments.length === 0) {

      document.getElementById("result").innerHTML =
        "<p>No attachments</p>";

      return;
    }

    const attachment = item.attachments[0];

    document.getElementById("result").innerHTML =
      "<p>Loading attachment...</p>";

    item.getAttachmentContentAsync(
      attachment.id,
      async function (result) {

        try {

          if (result.status !== Office.AsyncResultStatus.Succeeded) {

            document.getElementById("result").innerHTML =
              "<p>Failed to load attachment</p>";

            return;
          }

          const content = result.value.content;

          document.getElementById("result").innerHTML =
            "<p>Sending to localhost...</p>";

          const response = await fetch(
            "http://localhost:5001/process",
            {
              method: "POST",
              headers: {
                "Content-Type": "application/json"
              },
              body: JSON.stringify({
                fileName: attachment.name,
                contentBase64: content
              })
            });

          const data = await response.json();

          document.getElementById("result").innerHTML =
            "<p>SAVED: " + data.savedTo + "</p>";
        }
        catch (e) {

          document.getElementById("result").innerHTML =
            "<p>ERROR: " + e + "</p>";
        }
      });
  }
  catch (e) {

    document.getElementById("result").innerHTML =
      "<p>ERROR: " + e + "</p>";
  }
});
  }

  else {

    document.body.innerHTML =
      "<h1>No action</h1>";
  }

});